WITH enriched AS (SELECT *, COUNT(balance) OVER w_grp AS last3_count_balance, SUM(balance) OVER w_grp AS last3_sum_balance, MIN(balance) OVER w_grp AS last3_min_balance, NTILE(3) OVER w_part AS balance_bucket FROM accounts WINDOW w_grp AS (PARTITION BY customer_id, account_type ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY status, account_type ORDER BY balance DESC, id)) SELECT customer_id, COUNT(CASE WHEN account_type = 'LOAN' THEN 1 END) AS loan_count, PERCENTILE_APPROX(last3_count_balance, 0.5) AS last3_count_balance_p50 FROM enriched GROUP BY customer_id
